// Two-stage probability tree used to reverse a conditional probability.
//
// A two-argument size call bounds the output under Asymptote's default keepAspect
// and does not scale labels, so the compiler decides the box. This declaration is
// restated from a real compile by `npm run content:figures -- --record-aspect-ratios`.
size(415,361);
pen t = gray(0.55) + 1;
pen n = black + 1.4;
dot((0,0), n);
draw((0,0)--(4,2.2)..(0,0)--(4,-2.2), t);
dot((4,2.2), n);
dot((4,-2.2), n);
label("urn A", (4,2.2), N);
label("urn B", (4,-2.2), S);
draw((4,2.2)--(8,3.6)..(4,2.2)--(8,0.8), t);
draw((4,-2.2)--(8,-0.8)..(4,-2.2)--(8,-3.6), t);
dot((8,3.6), n);
dot((8,0.8), n);
dot((8,-0.8), n);
dot((8,-3.6), n);
label("red", (8,3.6), E);
label("blue", (8,0.8), E);
label("red", (8,-0.8), E);
label("blue", (8,-3.6), E);
label("two of three are red", (6,2.6), N);
label("urn B: one red", (6,-2.6), N);

// Dot diagram for the sum of two dice: one dot per ordered outcome.
//
// A two-argument size call bounds the output under Asymptote's default keepAspect
// and does not scale labels, so the compiler decides the box. This declaration is
// restated from a real compile by `npm run content:figures -- --record-aspect-ratios`.
size(367,301);
pen d = rgb(0.13,0.33,0.62) + 2pt;
pen e = rgb(0.74,0.33,0.13) + 2pt;
for (int k = 0; k < 6; k = k + 1) {
  dot((0.8+k,3.4), d);
  dot((0.8+k,2.2), d);
  dot((0.8+k,1.0), d);
  dot((0.8+k,-0.2), d);
  dot((2.6+k,-0.2), e);
}
draw((0.4,3.9)--(6.4,3.9), gray(0.55)+0.7);
draw((0.4,-0.7)--(6.4,-0.7), gray(0.55)+0.7);
label("four dots each", (3.4,4.3), N);
label("one dot each", (3.4,-1.1), S);
label("total $14$ dots, mean $14/6$", (7.2,1.6), W);
